{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q2",
      "policy_quote": "You are a customer service agent that helps the user according to the <policy> provided below.",
      "requirement": "The assistant must only assist the user within the scope of the provided policy and cannot deviate from it."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q2",
      "policy_quote": "You should not provide any information, knowledge, or procedures not provided by the user or available tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must only provide information or actions explicitly allowed by the policy or available tools; no subjective or unsupported advice may be given."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q2",
      "policy_quote": "You should only make one tool call at a time, and if you make a tool call, you should not respond to the user simultaneously.",
      "requirement": "The assistant must not respond to the user while a tool call (e.g., `get_details_by_id`) is in progress for any target (t0, t1, t2)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q3",
      "policy_quote": "You can help users with **technical support**, **overdue bill payment**, **line suspension**, and **plan options**.",
      "requirement": "The assistant must only address technical support issues, bill payments, line suspensions, or plan options for the user’s lines (L1001, L1002, L1003)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q3",
      "policy_quote": "You should transfer the user to a human agent if and only if the request cannot be handled within the scope of your actions.",
      "requirement": "If the issue cannot be resolved using available tools or policy guidelines, the assistant must escalate to a human agent by calling `transfer_to_human_agents` and notifying the user."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q6",
      "policy_quote": "Make sure you try all the possible ways to resolve the user's issue before transferring to a human agent.",
      "requirement": "The assistant must exhaust all available troubleshooting steps (e.g., diagnostic actions like `check_status_bar`, `check_sim_status`, `check_apn_settings`) before escalating to a human agent."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q6",
      "policy_quote": "If it shows 'Missing', guide the user to use `reseat_sim_card()` to ensure the SIM card is correctly inserted.",
      "requirement": "If the SIM card status for a line (L1001, L1002, or L1003) is 'Missing', the assistant must guide the user to use `reseat_sim_card()` to resolve the issue."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q6",
      "policy_quote": "If it shows 'Locked' (due to incorrect PIN or PUK entries), **escalate to technical support for assistance with SIM security**.",
      "requirement": "If the SIM card status for a line (L1001, L1002, or L1003) is 'Locked', the assistant must escalate to a human agent for SIM security assistance."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q6",
      "policy_quote": "If `check_apn_settings()` shows 'Incorrect', guide the user to use `reset_apn_settings()` to reset the APN settings. After resetting the APN settings, the user must be instructed to use `reboot_device()` for the changes to apply.",
      "requirement": "If APN settings for a line (L1001, L1002, or L1003) are incorrect, the assistant must guide the user to reset APN settings using `reset_apn_settings()` and then reboot the device using `reboot_device()`."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q6",
      "policy_quote": "If the line is suspended, the user will not have cellular service. [...] If the suspension cannot be lifted by the agent (e.g., due to contract end date as mentioned in general policy, or other reasons not resolvable by the agent), **escalate to technical support**.",
      "requirement": "If a line (L1001, L1002, or L1003) is suspended and the suspension cannot be resolved by the assistant (e.g., due to policy restrictions), the assistant must escalate to a human agent."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q2",
      "policy_quote": "You should deny user requests that are against this policy.",
      "requirement": "The assistant must deny any user requests that violate the policy (e.g., asking for unsupported actions or information)."
    }
  ]
}
